-- Idempotent product translations for the currently verified 79 active catalog products.
-- Generated from src/data/product-translations/batch-*.json; hashes follow productSourceHash().
BEGIN;
INSERT INTO public.storefront_translations (entity_type, entity_id, locale, source_hash, payload, updated_at)
SELECT 'product', incoming.entity_id, incoming.locale, incoming.source_hash, incoming.payload, now()
FROM jsonb_to_recordset($product_translation_rows$[{"entity_id":"111111111","locale":"en","source_hash":"7bbba485ca22fabba10253666b278cf1087319aafb84eb3684747c38e55eb64d","payload":{"name":"Aura Gold Sculpted Asymmetric White Jumpsuit","description":"The Aura White Jumpsuit brings modern elegance and luxury together through architectural lines and an iconic gold brooch detail.\n\nIts high neckline, asymmetric blazer-style bodice and fluid wide-leg cut create a striking silhouette for special occasions, engagement or wedding celebrations, and evening events. The draped crepe fabric does not cling to the body and offers comfortable polish throughout the day.\n\nKey features:\n\nSilhouette: High neck, sleeveless, asymmetric bodice\n\nDetail: Textured, custom-designed gold buckle/brooch at the waist\n\nCut: High waist with fluid wide legs\n\nStyling: Finish the look with nude- or gold-toned heels and minimal gold accessories.","fabric":"Satin & silk crepe","care":"Dry clean only using a delicate process. Keep direct heat and ironing away from the gold brooch detail. If needed, iron inside out at a low temperature."}},{"entity_id":"111111111","locale":"ar","source_hash":"7bbba485ca22fabba10253666b278cf1087319aafb84eb3684747c38e55eb64d","payload":{"name":"Aura Gold بتصميم أبيض غير متماثل","description":"يجمع جمبسوت Aura الأبيض بين الأناقة العصرية والفخامة، بخطوط معمارية وتفصيل بروش ذهبي لافت.\n\nتمنح الياقة العالية والجزء العلوي بأسلوب السترة غير المتماثل والقصة الواسعة الانسيابية إطلالة مميزة للمناسبات الخاصة واحتفالات الخطوبة أو الزفاف والفعاليات المسائية. لا يلتصق قماش الكريب المنسدل بالجسم، ويوفر أناقة مريحة طوال اليوم.\n\nأبرز التفاصيل:\n\nالقصة: ياقة عالية، بلا أكمام، وجزء علوي غير متماثل\n\nالتفصيل: إبزيم/بروش ذهبي ذو ملمس مميز ومصمم خصيصاً عند الخصر\n\nالقصّة: خصر مرتفع وساقان واسعتان بانسياب\n\nاقتراح تنسيق: أكملي الإطلالة بكعب بلون نيود أو ذهبي وإكسسوارات ذهبية بسيطة.","fabric":"ساتان وكريب حريري","care":"يُنظف جافاً فقط وبطريقة لطيفة. أبعدي التفصيل الذهبي عن الحرارة المباشرة والمكواة. عند الحاجة، اكويه من الداخل على حرارة منخفضة."}},{"entity_id":"11111222","locale":"en","source_hash":"7a24c68e9b562452721a4c9bccf5993d67cccfe23c3550785eb0d25ef75ed347","payload":{"name":"Beige Gathered Maxi Shirt Dress with Pockets","description":"The Sand Dress pairs the calm elegance of taupe tones with sculptural volume for a graceful, fluid look.\n\nWarm sand-beige colour meets a classic shirt collar, flap pockets at the chest and wide-cuffed 3/4-length sleeves. Dense gathers at the waist form a full A-line maxi skirt that falls softly. Side pockets and a substantial yet smooth, draped fabric bring everyday comfort and refined polish.\n\nKey features:\n• Cut: Shirt collar, flap chest pockets, 3/4-length sleeves with wide cuffs, and a voluminous gathered A-line skirt\n• Detail: Practical side pockets and a fluid, densely pleated maxi silhouette\n• Fabric texture: A luxurious crepe/poplin texture that is substantial, smooth, fluid and designed to hold its shape\n• Styling: Pair with a tonal beige scarf and stiletto boots for a monochrome city look.","fabric":"Double crepe","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"11111222","locale":"ar","source_hash":"7a24c68e9b562452721a4c9bccf5993d67cccfe23c3550785eb0d25ef75ed347","payload":{"name":"فستان قميص بيج طويل بكسرات وجيوب","description":"يجمع فستان Sand بين هدوء درجات التاوب والحجم النحتي ليمنح إطلالة انسيابية وأنيقة.\n\nيمتزج دفء البيج الرملي مع ياقة قميص كلاسيكية وجيوب بغطاء على الصدر وأكمام بطول 3/4 تنتهي بأساور عريضة. وتشكّل الكسرات الكثيفة عند الخصر تنورة ماكسي واسعة بقصة A تنساب إلى الأسفل. أما الجيوب الجانبية والقماش المتماسك ذي الملمس الناعم والانسيابي فيجمعان الراحة اليومية والرقي.\n\nأبرز التفاصيل:\n• القصّة: ياقة قميص، وجيوب صدر بغطاء، وأكمام 3/4 بأساور عريضة، وتنورة واسعة بقصة A مع كسرات عند الخصر\n• التفصيل: جيوب جانبية عملية وقصة ماكسي انسيابية بكسرات كثيفة\n• ملمس القماش: ملمس كريب/بوبلين فاخر متماسك وناعم وانسيابي، مصمم للحفاظ على شكله\n• اقتراح تنسيق: نسّقيه مع وشاح بيج بدرجات متقاربة وحذاء بكعب رفيع لإطلالة مدينة أحادية اللون.","fabric":"كريب مزدوج","care":"يُنظف جافاً فقط وبطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"amber-islemeli-asimetrik-kapusonlu-kaban","locale":"en","source_hash":"11230031ee237c0482072f2153d8302818e6a4bc01a6e782c0895ce1eaf482cf","payload":{"name":"Amber Embellished Asymmetric Hooded Coat","description":"The Amber Coat brings the richness of warm brown tones together with handcrafted sparkle and sculptural draping for a distinctive expression of outerwear luxury.\n\nThe deep chocolate-brown shade is framed by tonal leather-piped details along the hood and edges. Handcrafted crystal-bead embroidery in bronze and terracotta tones on the right chest adds an artistic accent. Its open front, fluid drape and asymmetric waterfall hem create sculptural movement with every step.\n\nKey features:\n• Cut: Hooded neckline, open front, long sleeves, and a fluid asymmetric hem\n• Detail: Leather-piped neckline and edges, a handcrafted crystal/bead branch motif on the chest, and leather-detailed pockets\n• Fabric texture: A substantial, soft, fluid luxury wool/cashmere-blend fabric designed to hold its shape\n• Styling: Pair with ecru or cream wide-leg trousers, silk blouses and stilettos for polished city style in cool weather.","fabric":"Silk crepe & satin","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"amber-islemeli-asimetrik-kapusonlu-kaban","locale":"ar","source_hash":"11230031ee237c0482072f2153d8302818e6a4bc01a6e782c0895ce1eaf482cf","payload":{"name":"معطف Amber مطرّز بغطاء رأس وقصة غير متماثلة","description":"يجمع معطف Amber ثراء درجات البني الدافئة مع اللمسات اللامعة المنفذة يدوياً والقصة المنسدلة ذات الطابع النحتي، ليقدم أسلوباً مميزاً في فخامة الملابس الخارجية.\n\nتحدّد درجة البني الشوكولاتي العميقة تفاصيل حواف جلدية بلون متقارب على غطاء الرأس والحواف. وتضيف زخرفة من الكريستال والخرز بدرجات البرونزي والطوبي، منفذة يدوياً على الجهة اليمنى من الصدر، لمسة فنية. تمنح الواجهة المفتوحة والانسياب والحافة الشلالية غير المتماثلة حركة نحتية مع كل خطوة.\n\nأبرز التفاصيل:\n• القصّة: ياقة بغطاء رأس، وواجهة مفتوحة، وأكمام طويلة، وحافة منسدلة غير متماثلة\n• التفصيل: حواف وياقة مبطنة بتفاصيل جلدية، وزخرفة غصن من الكريستال/الخرز منفذة يدوياً على الصدر، وجيوب بتفاصيل جلدية\n• ملمس القماش: قماش فاخر من مزيج الصوف/الكشمير، متماسك وناعم وانسيابي ومصمم للحفاظ على شكله\n• اقتراح تنسيق: نسّقيه مع بنطال واسع بلون إكرو أو كريمي وبلوزة حريرية وكعب رفيع لإطلالة مدينة أنيقة في الطقس البارد.","fabric":"كريب حريري وساتان","care":"يُنظف جافاً فقط وبطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"asdasd","locale":"en","source_hash":"b8591d0bdd838e1b3478507f33d10d92e620cae26c51af4f4c2a6a12837be496","payload":{"name":"Scarlet Lace-Trimmed Burgundy Jacket","description":"The Scarlet Burgundy Jacket brings classic tailoring together with feminine accents for a refined, sophisticated look.\n\nThe depth of burgundy is enriched with black lace trim along the side panels and lining. Designed for women who want to stand out in polished daytime office looks as well as evening occasions.\n\nKey features:\n\nCut: A tailored blazer shape that balances masculine lines with a fitted silhouette\n\nDetail: Contrasting black lace texture on the side panels and inner edges\n\nWear: An effortless transition from day to evening\n\nStyling: Pair with high-waisted black tailored trousers and stilettos or sneakers.","fabric":"Double crepe & cotton satin","care":"Professional dry clean only. Iron inside out at a low temperature. Do not apply steam or direct heat to the lace panels."}},{"entity_id":"asdasd","locale":"ar","source_hash":"b8591d0bdd838e1b3478507f33d10d92e620cae26c51af4f4c2a6a12837be496","payload":{"name":"سترة Scarlet بلون خمري وحواف من الدانتيل","description":"تجمع سترة Scarlet الخمرية بين فن الخياطة الكلاسيكية واللمسات الأنثوية، لتضفي على إطلالتك طابعاً راقياً وأنيقاً.\n\nيزداد عمق اللون الخمري غنىً بفضل حواف الدانتيل الأسود على الجانبين والبطانة. صُممت للمرأة التي ترغب في التميز بإطلالة مكتبية نهارية أنيقة أو في المناسبات المسائية.\n\nأبرز التفاصيل:\n\nالقصّة: قصة بليزر مفصلة توازن بين الخطوط المستوحاة من القصّات الرجالية والقوام المحدد\n\nالتفصيل: ملمس دانتيل أسود متباين على الجانبين والحواف الداخلية\n\nالاستخدام: انتقال سهل من إطلالة النهار إلى المساء\n\nاقتراح تنسيق: نسّقيها مع بنطال أسود مفصل بخصر مرتفع وحذاء بكعب رفيع أو حذاء رياضي.","fabric":"كريب مزدوج وساتان قطني","care":"يُنظف جافاً لدى مختصين فقط. يُكوى من الداخل على حرارة منخفضة. لا تستخدمي البخار أو الحرارة المباشرة على ألواح الدانتيل."}},{"entity_id":"aura-asimetrik-cift-renk-dokumlu-gomlek-ceket","locale":"en","source_hash":"3744357e5009a551c94c27cb59220f61a4b56e7244fa6c74cefa086be93405ee","payload":{"name":"Aura Two-Tone Draped Asymmetric Shirt Jacket","description":"Reflecting the harmony of contrasting colours and distinctive textures, the Aura Asymmetric Draped Shirt Jacket adds an artistic touch to your wardrobe with its modern silhouette.\n\nOne side is a simple ecru shade, while the other has a deep marbled/tie-dye pattern, creating a look with two distinct characters. The fluid asymmetric front panel brings movement to every step and creates an effortless signature look for the office or casual occasions.\n\nKey features:\n• Cut: Relaxed fit with an asymmetric, draped front panel\n• Detail: Two-tone colour-block design with a pattern and shirt collar\n• Styling: Pair with a black lace or plain bustier and high-waisted fluid trousers.","fabric":"Silk velvet & cotton","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"aura-asimetrik-cift-renk-dokumlu-gomlek-ceket","locale":"ar","source_hash":"3744357e5009a551c94c27cb59220f61a4b56e7244fa6c74cefa086be93405ee","payload":{"name":"سترة قميص Aura بلونين وانسياب وقصة غير متماثلة","description":"تعكس سترة القميص المنسدلة غير المتماثلة من Aura تناغم الألوان المتباينة والخامات المميزة، وتضيف إلى خزانة ملابسك لمسة فنية بقصتها العصرية.\n\nيأتي أحد جانبيها بدرجة إكرو بسيطة، بينما يحمل الجانب الآخر نقشاً عميقاً مموّجاً/بتأثير الربط والصباغة، لتقدم إطلالة بشخصيتين. تمنح الواجهة الأمامية المنسدلة وغير المتماثلة حركة مع كل خطوة، وتوفر مظهراً مميزاً بلا تكلف للعمل أو للمناسبات اليومية.\n\nأبرز التفاصيل:\n• القصّة: قصة مريحة مع لوحة أمامية منسدلة وغير متماثلة\n• التفصيل: تصميم كتلي بلونين ونقشة مع ياقة قميص\n• اقتراح تنسيق: نسّقيها مع توب دانتيل أسود أو توب بسيط وبنطال انسيابي بخصر مرتفع.","fabric":"مخمل حريري وقطن","care":"يُنظف جافاً فقط وبطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"autumn-goblen-cicek-desenli-yelek-ve-fular-seti","locale":"en","source_hash":"e868d04d70c3902cf33b962e5648a2d791c43d7981ddd20106c1156653036228","payload":{"name":"Autumn Gobelin Floral Vest and Scarf Set","description":"The Autumn Floral Vest Set brings the warm tones of autumn and winter together with a gobelin weave, pairing retro elegance with modern tailoring.\n\nIts richly floral fabric, classic V-neck button-front and pointed hem create a close fit at the waist. The matching neck scarf, made from the same fabric, completes the set with an artistic signature accent.\n\nKey features:\n• Set includes: A gobelin-patterned fabric vest and a matching neck scarf in the same texture\n• Cut: V-neck, button-front, short vest with a fitted back\n• Styling: Layer over a black lace or tulle blouse and pair with high-waisted fluid black trousers.","fabric":"Flannel fabric","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"autumn-goblen-cicek-desenli-yelek-ve-fular-seti","locale":"ar","source_hash":"e868d04d70c3902cf33b962e5648a2d791c43d7981ddd20106c1156653036228","payload":{"name":"طقم سترة Autumn بنقشة غوبلان زهرية ووشاح","description":"يجمع طقم السترة الزهرية Autumn بين درجات الخريف والشتاء الدافئة ونسيج الغوبلان، مقدماً أناقة بطابع كلاسيكي مع خياطة عصرية.\n\nيتميز بقماش غني بالزخارف الزهرية وياقة V كلاسيكية وأزرار أمامية وحافة مدببة، مع قصة تحدد الخصر. ويكمل وشاح الرقبة المصنوع من القماش نفسه الطقم بلمسة فنية مميزة.\n\nأبرز التفاصيل:\n• محتويات الطقم: سترة من قماش بنقشة غوبلان ووشاح رقبة من الملمس نفسه\n• القصّة: ياقة V، وأزرار أمامية، وسترة قصيرة بظهر محدد\n• اقتراح تنسيق: ارتديها فوق بلوزة دانتيل أو تول سوداء ونسّقيها مع بنطال أسود انسيابي بخصر مرتفع.","fabric":"قماش فلانيل","care":"يُنظف جافاً فقط وبطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"azure-geometrik-desenli-dugmeli-maxi-elbise","locale":"en","source_hash":"07f39a7fb295842d26ab7f92b2284096fda74389d9a94ea8bb387dc6d67777c5","payload":{"name":"Azure Geometric Print Button-Front Maxi Dress","description":"The Azure Dress pairs a vivid colour palette with modern abstract forms for effortless, high-energy daytime style.\n\nIts abstract mosaic print brings together blue, green, yellow and black. A classic shirt collar and half button-front keep the design timeless. Gathers at the waist shape a fluid, full maxi skirt for comfortable elegance throughout the day.\n\nKey features:\n• Cut: Shirt collar, button-front, long sleeves with cuffs, gathered waist and maxi-length silhouette\n• Detail: Contrasting royal-blue collar and cuffs with an abstract geometric mosaic print\n• Fabric texture: Lightweight, fluid, breathable and soft viscose texture\n• Styling: Pair with a royal-blue or ecru scarf and minimalist white sneakers or ballet flats for a dynamic city look.","fabric":"Viscose","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"azure-geometrik-desenli-dugmeli-maxi-elbise","locale":"ar","source_hash":"07f39a7fb295842d26ab7f92b2284096fda74389d9a94ea8bb387dc6d67777c5","payload":{"name":"فستان Azure طويل بنقشة هندسية وأزرار أمامية","description":"يجمع فستان Azure لوحة ألوان حيوية مع أشكال تجريدية عصرية لإطلالة نهارية مفعمة بالحيوية وبلا تكلف.\n\nتضم طباعته الفسيفسائية التجريدية درجات الأزرق والأخضر والأصفر والأسود. وتحافظ ياقة القميص الكلاسيكية والإغلاق الأمامي الجزئي بالأزرار على طابع خالد. أما الكسرات عند الخصر فتمنح التنورة الطويلة حجماً وانسياباً لأناقة مريحة طوال اليوم.\n\nأبرز التفاصيل:\n• القصّة: ياقة قميص، وأزرار أمامية، وأكمام طويلة بأساور، وخصر بكسرات وقصة ماكسي\n• التفصيل: ياقة وأساور متباينة باللون الأزرق الملكي مع طبعة فسيفسائية تجريدية هندسية\n• ملمس القماش: ملمس فيسكوز خفيف وانسيابي وجيد التهوية وناعم\n• اقتراح تنسيق: نسّقيه مع وشاح أزرق ملكي أو إكرو وحذاء رياضي أبيض بسيط أو حذاء باليه لإطلالة مدينة حيوية.","fabric":"فيسكوز","care":"يُنظف جافاً فقط وبطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"azure-sal-desenli-saks-mavi-ipek-palazzo-pantolon","locale":"en","source_hash":"d11ac923b2b7e5e3286e9110692a850a388245696ea86508decc0fae8c2c3f41","payload":{"name":"Azure Royal-Blue Silk Paisley Palazzo Trousers","description":"The Azure Palazzo Trousers bring together ornate paisley motifs and the depth of royal blue in a graceful, fluid silhouette.\n\nA wide bordered waistband defines the high waist, while deep pleats and fluid maxi-length wide legs move with the ease of a skirt. A dotted lower-leg border and concealed side pockets bring practicality to the polished design.\n\nKey features:\n• Cut: High waist, wide waistband, front pleats and extra-wide palazzo/skirt-trouser legs\n• Print: Rich paisley motifs in royal blue, green and tan, with a dotted hem border\n• Styling: Pair with royal-blue or ecru tops, gold-tone jewellery and stilettos or sandals for a signature look.","fabric":"Silk","care":"Dry clean only using a delicate process, or hand wash in cold water. Dry flat; do not hang."}},{"entity_id":"azure-sal-desenli-saks-mavi-ipek-palazzo-pantolon","locale":"ar","source_hash":"d11ac923b2b7e5e3286e9110692a850a388245696ea86508decc0fae8c2c3f41","payload":{"name":"بنطال Azure حريري واسع بنقشة بيزلي أزرق ملكي","description":"يجمع بنطال Azure بالازو بين زخارف البيزلي الغنية وعمق الأزرق الملكي في قصة أنيقة وانسيابية.\n\nيبرز حزام الخصر العريض ذو الحافة المحددة الخصر المرتفع، بينما تمنح الكسرات العميقة والساقان الواسعتان بطول ماكسي حركة انسيابية تشبه التنورة. وتضيف الحافة السفلية المنقطة والجيوب الجانبية المخفية لمسة عملية إلى التصميم الأنيق.\n\nأبرز التفاصيل:\n• القصّة: خصر مرتفع، وحزام عريض، وكسرات أمامية، وساقان واسعتان جداً بقصة بالازو/بنطال يشبه التنورة\n• النقشة: زخارف بيزلي غنية بالأزرق الملكي والأخضر والجملي، مع حافة سفلية منقطة\n• اقتراح تنسيق: نسّقيه مع قطع علوية بالأزرق الملكي أو الإكرو ومجوهرات ذهبية اللون وحذاء بكعب رفيع أو صنادل لإطلالة مميزة.","fabric":"حرير","care":"يُنظف جافاً فقط وبطريقة لطيفة، أو يُغسل يدوياً بماء بارد. يُجفف ممدوداً على سطح مستوٍ؛ لا يُعلّق."}},{"entity_id":"azure-sal-desenli-saks-mavi-ipek-palazzo-pantolon-kopya","locale":"en","source_hash":"3b1a50de58e6fa035b9663593f68bbe2ae8de610d8de86954bec0e9980b9f4d1","payload":{"name":"Azure Indigo Paisley Trousers","description":"The Azure Palazzo Trousers bring together ornate paisley motifs and the depth of indigo blue in a graceful, fluid silhouette.\n\nA wide bordered waistband defines the high waist, while deep pleats and fluid maxi-length wide legs move with the ease of a skirt. The dotted lower-leg border adds a practical finishing detail.\n\nKey features:\n• Cut: High waist, wide waistband, front pleats and extra-wide palazzo/skirt-trouser legs\n• Print: Rich paisley motifs in indigo, olive green and tan, with a lower-leg border\n• Styling: Pair with fine-strap tops or cream chiffon shirts.","fabric":"Silk","care":"Dry clean only using a delicate process, or hand wash in cold water. Dry flat; do not hang."}},{"entity_id":"azure-sal-desenli-saks-mavi-ipek-palazzo-pantolon-kopya","locale":"ar","source_hash":"3b1a50de58e6fa035b9663593f68bbe2ae8de610d8de86954bec0e9980b9f4d1","payload":{"name":"بنطال Azure بنقشة بيزلي بلون نيلي","description":"يجمع بنطال Azure بالازو بين زخارف البيزلي الغنية وعمق الأزرق النيلي في قصة أنيقة وانسيابية.\n\nيبرز حزام الخصر العريض ذو الحافة المحددة الخصر المرتفع، بينما تمنح الكسرات العميقة والساقان الواسعتان بطول ماكسي حركة انسيابية تشبه التنورة. وتضيف الحافة المنقطة أسفل الساق لمسة عملية نهائية.\n\nأبرز التفاصيل:\n• القصّة: خصر مرتفع، وحزام عريض، وكسرات أمامية، وساقان واسعتان جداً بقصة بالازو/بنطال يشبه التنورة\n• النقشة: زخارف بيزلي غنية بالنيلي والأخضر الزيتوني والجملي، مع حافة أسفل الساق\n• اقتراح تنسيق: نسّقيه مع توب بحمالات رفيعة أو قميص شيفون كريمي.","fabric":"حرير","care":"يُنظف جافاً فقط وبطريقة لطيفة، أو يُغسل يدوياً بماء بارد. يُجفف ممدوداً على سطح مستوٍ؛ لا يُعلّق."}},{"entity_id":"azure-v-yaka-karpuz-kol-crop-bluz","locale":"en","source_hash":"b7d0f2dd95d6cd34621d657b104d98a6ecade6a33fe2d9f80da41b8eeb1bdc87","payload":{"name":"Azure V-Neck Puff-Sleeve Cropped Top","description":"The Azure Blouse pairs minimalist lines with romantic sleeve details for effortless, modern city style.\n\nIts graceful V-neck and puff sleeves, gently gathered at the shoulders, add a dynamic and feminine feel. The modern cropped length ends at the waist and balances beautifully with high-waisted trousers and skirts.\n\nKey features:\n• Cut: V-neck, short puff sleeves and a relaxed, lightly cropped silhouette\n• Detail: Gathers at the shoulders and sleeve hems, with a breathable linen/cotton texture\n• Fabric texture: Lightweight, substantial and wrinkle-resistant linen-look fabric\n• Styling: Pair with high-waisted ecru wide-leg trousers and tan accessories for effortless daytime polish.","fabric":"Modal silk","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"azure-v-yaka-karpuz-kol-crop-bluz","locale":"ar","source_hash":"b7d0f2dd95d6cd34621d657b104d98a6ecade6a33fe2d9f80da41b8eeb1bdc87","payload":{"name":"بلوزة Azure قصيرة بياقة V وأكمام منتفخة","description":"تجمع بلوزة Azure بين الخطوط البسيطة وتفاصيل الأكمام الرومانسية لإطلالة مدينة عصرية وبلا تكلف.\n\nتضفي ياقة V الأنيقة والأكمام المنتفخة ذات الكسرات الخفيفة عند الكتفين طابعاً حيوياً وأنثوياً. وينتهي الطول القصير العصري عند الخصر، ليتوازن بانسجام مع البناطيل والتنانير ذات الخصر المرتفع.\n\nأبرز التفاصيل:\n• القصّة: ياقة V، وأكمام قصيرة منتفخة، وقصة مريحة قصيرة قليلاً\n• التفصيل: كسرات عند الكتفين وحواف الأكمام، مع ملمس كتاني/قطني جيد التهوية\n• ملمس القماش: قماش خفيف ومتماسك ومقاوم للتجعد بمظهر الكتان\n• اقتراح تنسيق: نسّقيها مع بنطال واسع بلون إكرو وخصر مرتفع وإكسسوارات بلون جملي لإطلالة نهارية أنيقة بلا تكلف.","fabric":"حرير مودال","care":"يُنظف جافاً فقط وبطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"blush-etnik-cicek-desenli-mercan-pembe-ipek-palazzo-pantolon","locale":"en","source_hash":"198f4c5893b7162e57828ed3d2e49dec472a8fa6ffeda1690ade9494e9e44481","payload":{"name":"Blush Coral-Pink Silk Paisley Palazzo Trousers","description":"The Blush Palazzo Trousers bring colour and elegance to every step with purple and indigo floral motifs on a coral-pink ground.\n\nA patterned waistband and front pleats at the high waist create a fluid look that lengthens the silhouette. A purple-violet border at the hem and concealed side pockets combine polish with practicality.\n\nKey features:\n• Cut: High waist, wide waistband, front pleats and extra-wide fluid palazzo/skirt-trouser legs\n• Print: Ethnic floral motifs in coral pink, purple and blue, with a matching hem border\n• Styling: Pair with cropped tops in pink or purple, gold-tone jewellery and stilettos or sandals.","fabric":"Silk","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"blush-etnik-cicek-desenli-mercan-pembe-ipek-palazzo-pantolon","locale":"ar","source_hash":"198f4c5893b7162e57828ed3d2e49dec472a8fa6ffeda1690ade9494e9e44481","payload":{"name":"بنطال Blush حريري واسع باللون الوردي المرجاني ونقشة زهرية","description":"يضيف بنطال Blush بالازو اللون والأناقة إلى خطواتك، بزخارف زهرية بنفسجية ونيليّة على خلفية وردية مرجانية.\n\nيمنح حزام الخصر المنقوش والكسرات الأمامية عند الخصر المرتفع مظهراً انسيابياً يطيل القوام. وتجمع الحافة البنفسجية عند الأسفل والجيوب الجانبية المخفية بين الأناقة والعملية.\n\nأبرز التفاصيل:\n• القصّة: خصر مرتفع، وحزام عريض، وكسرات أمامية، وساقان واسعتان جداً بانسياب بقصة بالازو/بنطال يشبه التنورة\n• النقشة: زخارف زهرية بطابع إثني بدرجات الوردي المرجاني والبنفسجي والأزرق مع حافة متناسقة أسفل الساق\n• اقتراح تنسيق: نسّقيه مع قطع علوية قصيرة بالوردي أو البنفسجي ومجوهرات ذهبية اللون وحذاء بكعب رفيع أو صنادل.","fabric":"حرير","care":"يُنظف جافاً فقط وبطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"botanical-cross-stitch-nakisli-nevresim-takimi","locale":"en","source_hash":"d500909ce6909de5def36e53cf42529b4a3e8dfb23b4663d2d2bd019270116b4","payload":{"name":"Botanical Cross-Stitch Embroidered Bedding Set","description":"The Botanical Cross-Stitch Bedding Set brings the look of traditional handcraft into the bedroom with a modern, refined touch, creating a fresh and peaceful atmosphere.\n\nColourful floral-garland motifs in an etamine/cross-stitch style are embroidered on smooth white cotton satin, adding timeless elegance and a nostalgic note. Vivid floral embroidery runs in vertical bands on the pillowcases and in horizontal, rhythmic stripes along the duvet-cover hem, lending the bedroom a distinctive character.\n\nKey features:\n• Contents: 1 double duvet cover (200x220 cm), 1 sheet (240x260 cm), 2 embroidered pillowcases (50x70 cm)\n• Detail: Colourful etamine cross-stitch embroidery on the duvet-cover hem and pillowcases; concealed-button duvet closure\n• Fabric texture: Breathable, high thread-count, silk-soft 100% cotton satin\n• Styling: Pair with a neutral or beige headboard, wood details and fresh white flowers for a warm, refined and peaceful bedroom atmosphere.","fabric":"","care":""}},{"entity_id":"botanical-cross-stitch-nakisli-nevresim-takimi","locale":"ar","source_hash":"d500909ce6909de5def36e53cf42529b4a3e8dfb23b4663d2d2bd019270116b4","payload":{"name":"طقم مفروشات Botanical مطرّز بغرز متقاطعة نباتية","description":"ينقل طقم مفروشات Botanical Cross-Stitch جمالية الحرف التقليدية إلى غرفة النوم بلمسة عصرية راقية، ليخلق أجواء منعشة وهادئة.\n\nتُطرز زخارف أكاليل زهرية ملونة بأسلوب الإيتامين/الغرز المتقاطعة على ساتان قطني أبيض ناعم، فتضيف أناقة خالدة ولمسة حنين. تمتد الزخارف الزهرية الزاهية في خطوط عمودية على أغطية الوسائد، وفي أشرطة أفقية متناسقة على حافة غطاء اللحاف، لتمنح غرفة النوم طابعاً مميزاً.\n\nأبرز التفاصيل:\n• المحتويات: غطاء لحاف مزدوج واحد (200x220 سم)، وملاءة واحدة (240x260 سم)، وغطاءا وسادة مطرزان (50x70 سم)\n• التفصيل: تطريز إيتامين ملون بغرز متقاطعة على حافة غطاء اللحاف وأغطية الوسائد؛ إغلاق غطاء اللحاف بأزرار مخفية\n• ملمس القماش: ساتان قطني 100% ناعم كالحرير، جيد التهوية وعالي كثافة الخيوط\n• اقتراح تنسيق: نسّقيه مع لوح رأس بدرجات محايدة أو بيج وتفاصيل خشبية وزهور بيضاء نضرة لأجواء غرفة نوم دافئة وراقية وهادئة.","fabric":"","care":""}},{"entity_id":"burgundy-embroidered-kalem-elbise","locale":"en","source_hash":"c3474883bbeae3f979a1f23ee8b1071a0dee2631200196dbbf5cf7ac26f68e1b","payload":{"name":"Burgundy Embroidered Pencil Dress","description":"The Burgundy Pencil Dress pairs the depth of burgundy and plum tones with refined tailoring for an elegant, sculptural silhouette.\n\nBlending a high neckline with a square neckline and a modern keyhole opening, the design features softly structured shoulders and long sleeves with extended cuffs. Hand-finished floral embroidery in understated blue tones at the right waist adds an artistic, distinctive touch. The knee-length pencil cut follows the body's lines.\n\nKey features:\n• Cut: High neckline with a square keyhole opening, long sleeves with gathered shoulders and cuffs, fitted knee-length pencil silhouette\n• Detail: Blue-toned floral embroidery at the waist and a back slit\n• Fabric texture: A smooth, substantial, flexible crepe with a structured drape\n• Styling: Pair with burgundy stilettos and minimal gold jewellery for dinners, launches and special occasions.","fabric":"Cotton & polyester","care":"Dry clean only using a delicate process, or hand-wash in cold water. Dry flat; do not hang."}},{"entity_id":"burgundy-embroidered-kalem-elbise","locale":"ar","source_hash":"c3474883bbeae3f979a1f23ee8b1071a0dee2631200196dbbf5cf7ac26f68e1b","payload":{"name":"فستان Burgundy مطرّز بقصة قلم","description":"يجمع فستان Burgundy بقصة القلم بين عمق درجات الخمري والبرقوقي والخياطة الراقية، ليمنح إطلالة أنيقة ذات طابع نحتي.\n\nيمزج التصميم بين ياقة عالية وياقة مربعة مع فتحة عصرية، وتكتمل ملامحه بأكتاف محددة برفق وأكمام طويلة ذات أساور ممتدة. وتضيف زخرفة زهرية منفذة يدوياً بدرجات زرقاء هادئة عند الخصر من الجهة اليمنى لمسة فنية مميزة. تتبع القصة بالقلم بطول الركبة خطوط الجسم.\n\nأبرز التفاصيل:\n• القصّة: ياقة عالية مع فتحة مربعة، وأكمام طويلة بأكتاف وأساور مجمعة، وقصة قلم محددة بطول الركبة\n• التفصيل: تطريز زهري بدرجات الأزرق عند الخصر وفتحة خلفية\n• ملمس القماش: كريب ناعم ومتماسك ومرن بانسدال يحافظ على شكله\n• اقتراح تنسيق: نسّقيه مع حذاء خمري بكعب رفيع ومجوهرات ذهبية بسيطة للعشاء وحفلات الإطلاق والمناسبات الخاصة.","fabric":"قطن وبوليستر","care":"يُنظف جافاً فقط بطريقة لطيفة، أو يُغسل يدوياً بماء بارد. يُجفف مفروداً ولا يُعلّق."}},{"entity_id":"charcoal-asimetrik-volanli","locale":"en","source_hash":"02f7ecb87481b2be76191c80d656a67fee4673a2ff0cbf040cd11966b956d180","payload":{"name":"Charcoal Asymmetric Ruffle Suit","description":"Reinterpreting modern tailoring with dramatic, sculptural details, the Charcoal Jacket creates a polished, confident silhouette.\n\nThe sophisticated smoky-grey shade meets a single-button double-breasted closure and a collarless V neckline. An asymmetric draped ruffle extending to knee level on the right makes the design distinctive. Its fitted shape and sculptural drape give the jacket an artistic elegance beyond conventional styles.\n\nKey features:\n• Cut: Collarless V neckline, single-button double-breasted front, long sleeves and a fitted asymmetric shape\n• Detail: A dramatic, tiered ruffle/drape extending down from the right hem\n• Fabric texture: A substantial, shape-retaining crepe/wool-blend texture with a tailored feel\n• Styling: Pair with black high-waisted wide-leg trousers and pointed-toe heels for a striking occasion or work look.","fabric":"Lightweight denim","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"charcoal-asimetrik-volanli","locale":"ar","source_hash":"02f7ecb87481b2be76191c80d656a67fee4673a2ff0cbf040cd11966b956d180","payload":{"name":"طقم Charcoal بقصة كشكش غير متماثلة","description":"يعيد تصميم Charcoal Jacket تفسير الخياطة العصرية بتفاصيل درامية ذات طابع نحتي، ليمنح إطلالة متقنة وواثقة.\n\nيلتقي اللون الرمادي الدخاني الراقي بإغلاق مزدوج الصدر بزر واحد وياقة V بلا طية. وتبرز القصة بقطعة درابيه مكشكشة غير متماثلة تمتد حتى مستوى الركبة من الجهة اليمنى. يمنحها الشكل المحدد والانسياب النحتي أناقة فنية تتجاوز تصاميم السترات المعتادة.\n\nأبرز التفاصيل:\n• القصّة: ياقة V بلا طية، وإغلاق مزدوج الصدر بزر واحد، وأكمام طويلة وقصة محددة غير متماثلة\n• التفصيل: امتداد درابيه/كشكش درامي متعدد الطبقات من الحافة اليمنى\n• ملمس القماش: ملمس كريب/صوف متماسك يحافظ على شكله بطابع مفصل\n• اقتراح تنسيق: نسّقيه مع بنطال أسود واسع الساق بخصر مرتفع وحذاء مدبب بكعب لإطلالة لافتة للمناسبات أو العمل.","fabric":"دنيم خفيف","care":"يُنظف جافاً فقط بطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"elysian-asimetrik-yaka-drape-katmanli-kahve-midi-elbise","locale":"en","source_hash":"06fda801d0db38d1e0b2a559cd37bd4a1cfd48a2867fbe370d1dc1c8ba07d018","payload":{"name":"Elysian Asymmetric-Neck Draped Brown Midi Dress","description":"Bringing sculptural forms together with contemporary tailoring, the Elysian Dress makes a striking impression in deep chocolate brown.\n\nA high asymmetric neckline rising at the right shoulder, a deep V opening and layered draping from the waist toward the skirt create a considered architectural shape. A subtle front slit adds a graceful, dynamic flow to each step.\n\nKey features:\n• Cut: Asymmetric high neckline, sleeveless, deep V opening and fitted midi length\n• Detail: Layered fabric draping at the waist and skirt, with a front slit\n• Fabric texture: A substantial, shape-retaining crepe texture\n• Styling: Pair with minimal gold or bronze earrings and strappy heels for effortless occasion dressing.","fabric":"Cotton & polyester","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"elysian-asimetrik-yaka-drape-katmanli-kahve-midi-elbise","locale":"ar","source_hash":"06fda801d0db38d1e0b2a559cd37bd4a1cfd48a2867fbe370d1dc1c8ba07d018","payload":{"name":"فستان Elysian بني ميدي برقبة غير متماثلة ودرابيه","description":"يجمع فستان Elysian بين الأشكال النحتية والخياطة المعاصرة، ويتميز بدرجة بنية شوكولاتية عميقة.\n\nترتفع ياقة عالية غير متماثلة عند الكتف الأيمن، مع فتحة V عميقة ودرابيه متعدد الطبقات يمتد من الخصر نحو التنورة ليصوغ شكلاً معمارياً مدروساً. وتضيف الفتحة الأمامية الهادئة انسياباً أنيقاً وحيوياً مع كل خطوة.\n\nأبرز التفاصيل:\n• القصّة: ياقة عالية غير متماثلة، بلا أكمام، وفتحة V عميقة وطول ميدي محدد\n• التفصيل: طبقات من القماش المنسدل عند الخصر والتنورة مع فتحة أمامية\n• ملمس القماش: كريب متماسك يحافظ على شكله\n• اقتراح تنسيق: نسّقيه مع أقراط ذهبية أو برونزية بسيطة وحذاء بكعب ذي أشرطة لإطلالة مناسبة أنيقة بلا تكلف.","fabric":"قطن وبوليستر","care":"يُنظف جافاً فقط بطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"elysian-ekose-tuvit-blazer-ceket","locale":"en","source_hash":"45789e25cec3700c66c5a93ec7aeee9449a2a4117334c9d567c3890d5b664c9d","payload":{"name":"Elysian Plaid Tweed Blazer","description":"The Elysian Tweed Blazer brings classic tweed texture together with modern, confident checks, making it a versatile and timeless wardrobe piece.\n\nIts rich fabric reflects a harmonious blend of burgundy, grey and black, while the fitted cut sits neatly on the body. It offers a polished look with little effort, whether styled for the office or the weekend.","fabric":"Chanel-style fabric (100% satin lining)","care":""}},{"entity_id":"elysian-ekose-tuvit-blazer-ceket","locale":"ar","source_hash":"45789e25cec3700c66c5a93ec7aeee9449a2a4117334c9d567c3890d5b664c9d","payload":{"name":"سترة Elysian من التويد بنقشة مربعات","description":"تجمع سترة Elysian من التويد بين ملمس التويد الكلاسيكي ونقشة المربعات العصرية الجريئة، لتكون قطعة متعددة الاستخدامات وخالدة في خزانة الملابس.\n\nتعكس خامتها الغنية تناغماً بين الخمري والرمادي والأسود، فيما تستقر القصة المحددة بأناقة على الجسم. تمنح إطلالة متقنة بسهولة، سواء نُسقت للعمل أو لعطلة نهاية الأسبوع.","fabric":"قماش بطراز شانيل (بطانة من الساتان 100%)","care":""}},{"entity_id":"elysian-ekose-tuvit-blazer-ceket-kopya","locale":"en","source_hash":"6e4742ad338db3abcf0d3edec26fad6ffa4384774ec8aae9bc2b5c26cce77bad","payload":{"name":"Elysian Plaid Tweed Mini Skirt","description":"The Elysian Mini Skirt brings rich tweed texture together with lively checks for a timeless, confident look.\n\nIts distinctive fabric combines burgundy, grey and black tones. The high-waisted cut follows the silhouette and creates a leg-lengthening line, while offering comfortable polish throughout the day.","fabric":"Chanel-style fabric (100% satin lining)","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"elysian-ekose-tuvit-blazer-ceket-kopya","locale":"ar","source_hash":"6e4742ad338db3abcf0d3edec26fad6ffa4384774ec8aae9bc2b5c26cce77bad","payload":{"name":"تنورة Elysian قصيرة من التويد بنقشة مربعات","description":"تجمع تنورة Elysian القصيرة بين ملمس التويد الغني ونقشة المربعات الحيوية لإطلالة واثقة وخالدة.\n\nتتناغم في خامتها المميزة درجات الخمري والرمادي والأسود. وتحدد القصة ذات الخصر المرتفع القوام وتمنح الساقين مظهراً أطول، مع أناقة مريحة طوال اليوم.","fabric":"قماش بطراز شانيل (بطانة من الساتان 100%)","care":"يُنظف جافاً فقط بطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"elysian-ekose-tuvit-blazer-etek-kopya","locale":"en","source_hash":"f63cb28c74c5c9871d5e7218f44d6f192d53ee04c6f8d02105a6e5a30ff08279","payload":{"name":"Elysian Plaid Tweed Two-Piece Suit","description":"The Elysian Mini Skirt brings rich tweed texture together with lively checks for a timeless, confident look.\n\nIts distinctive fabric combines burgundy, grey and black tones. The high-waisted cut follows the silhouette and creates a leg-lengthening line, while offering comfortable polish throughout the day.","fabric":"Chanel-style fabric (100% satin lining)","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"elysian-ekose-tuvit-blazer-etek-kopya","locale":"ar","source_hash":"f63cb28c74c5c9871d5e7218f44d6f192d53ee04c6f8d02105a6e5a30ff08279","payload":{"name":"طقم Elysian من قطعتين بتويد ونقشة مربعات","description":"تجمع تنورة Elysian القصيرة بين ملمس التويد الغني ونقشة المربعات الحيوية لإطلالة واثقة وخالدة.\n\nتتناغم في خامتها المميزة درجات الخمري والرمادي والأسود. وتحدد القصة ذات الخصر المرتفع القوام وتمنح الساقين مظهراً أطول، مع أناقة مريحة طوال اليوم.","fabric":"قماش بطراز شانيل (بطانة من الساتان 100%)","care":"يُنظف جافاً فقط بطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"etoile-bros-detayli-uzun-siyah-ceket-elbise","locale":"en","source_hash":"6d3d226dced9af247d05361c3bc1fc50a4f40f0c910ab40de6a512f473253acb","payload":{"name":"Etoile Long Black Blazer Dress with Brooch","description":"Blending masculine tailoring with a feminine silhouette, the Etoile Blazer Dress offers timeless polish with a graceful, confident presence.\n\nA classic double-breasted neckline, vertical side button closure and sparkling star brooch attached at the lapel add a refined finish. Its gently body-skimming midi-to-maxi length makes it a distinctive choice for formal occasions and special dinners.\n\nKey features:\n• Cut: Fitted long blazer-dress silhouette that follows the body\n• Neckline & closure: Notched lapel/double-breasted shape with buttons running down the side\n• Accessory: Removable crystal-stone star brooch at the lapel\n• Styling: Complete the look with black stilettos and an elegant clutch.","fabric":"Polyester (100% satin lining)","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"etoile-bros-detayli-uzun-siyah-ceket-elbise","locale":"ar","source_hash":"6d3d226dced9af247d05361c3bc1fc50a4f40f0c910ab40de6a512f473253acb","payload":{"name":"فستان سترة Etoile أسود طويل مع بروش","description":"يمزج فستان السترة Etoile بين الخياطة المستوحاة من القصات الرجالية والقوام الأنثوي، ليقدم أناقة خالدة وحضوراً واثقاً.\n\nتضفي الياقة الكلاسيكية مزدوجة الصدر، وإغلاق الأزرار العمودي على الجانب، وبروش النجمة اللامع المثبت عند الياقة لمسة راقية. ويجعله الطول الميدي إلى الماكسي الذي ينساب برفق حول الجسم خياراً مميزاً للمناسبات الرسمية والعشاء الخاص.\n\nأبرز التفاصيل:\n• القصّة: قصة فستان سترة طويل ومحدد يتبع خطوط الجسم\n• الياقة والإغلاق: ياقة بطية/شكل مزدوج الصدر مع أزرار تمتد على الجانب\n• الإكسسوار: بروش نجمة قابل للإزالة مرصع بأحجار كريستالية عند الياقة\n• اقتراح تنسيق: أكملي الإطلالة بحذاء أسود بكعب رفيع وحقيبة كلاتش أنيقة.","fabric":"بوليستر (بطانة من الساتان 100%)","care":"يُنظف جافاً فقط بطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"fringed-tweed-crystal-tokali-ceket-takim","locale":"en","source_hash":"d8738c7d0fc1898851ce4e5974e5497fe1cfb49f1a5fde6d507c96d417899093","payload":{"name":"Fringed Tweed Crystal-Buckle Suit","description":"The Fringed Tweed Suit brings tactile richness together with luxurious accessories for a sophisticated take on modern tailoring.\n\nThe textured tweed jacket stands out with ecru check lines against a black ground, finished with lively fringe details along the collar, front placket and cuffs. A crystal-embroidered bow-shaped metal buckle at the waist creates a jewellery-like accent. The coordinating black, high-waisted palazzo trousers have a pressed crease and fluid wide legs, giving the silhouette a long, balanced line.\n\nKey features:\n• Cut: Classic-lapel fitted tweed jacket with a crystal buckle, paired with high-waisted fluid wide-leg trousers\n• Detail: Raw fringe along the collar, front edges and cuffs; custom buckle with crystal stones\n• Fabric texture: A substantial, shape-retaining tweed jacket with fluid crepe trousers\n• Styling: Pair with black patent stilettos and minimal crystal earrings for an easy transition from work meetings to evening occasions.","fabric":"Cotton & viscose","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"fringed-tweed-crystal-tokali-ceket-takim","locale":"ar","source_hash":"d8738c7d0fc1898851ce4e5974e5497fe1cfb49f1a5fde6d507c96d417899093","payload":{"name":"طقم Fringed Tweed بإبزيم كريستالي","description":"يجمع طقم Fringed Tweed بين ثراء الملمس والإكسسوارات الفاخرة ليقدم تفسيراً راقياً للخياطة العصرية.\n\nتتميز سترة التويد ذات الملمس الواضح بخطوط مربعات إكرو على خلفية سوداء، وتكتمل بحواف هدب حيوية عند الياقة وفتحة الأمام والأساور. ويشكل الإبزيم المعدني عند الخصر، المصمم كفيونكة ومطرز بالكريستال، لمسة تشبه المجوهرات. أما البنطال البالازو الأسود المتناسق، بخصره المرتفع وخط الكي وساقيه الواسعتين المنسدلتين، فيمنح القوام خطاً طويلاً ومتوازناً.\n\nأبرز التفاصيل:\n• القصّة: سترة تويد محددة بياقة كلاسيكية وإبزيم كريستالي، مع بنطال واسع وانسيابي بخصر مرتفع\n• التفصيل: هدب غير مشذّب على الياقة والحواف الأمامية والأساور؛ وإبزيم خاص بأحجار كريستالية\n• ملمس القماش: سترة تويد متماسكة تحافظ على شكلها مع بنطال كريب منسدل\n• اقتراح تنسيق: نسّقيه مع حذاء أسود لامع بكعب رفيع وأقراط كريستالية بسيطة للانتقال بسهولة من اجتماعات العمل إلى المناسبات المسائية.","fabric":"قطن وفيسكوز","care":"يُنظف جافاً فقط بطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"grey-houndstooth-yuksek-bel-kalem-etek","locale":"en","source_hash":"e788e2886a999c4f6bf9e01d73441af8bbc7c7717a56bb06d45fb436fd10b1be","payload":{"name":"Grey Houndstooth High-Waisted Pencil Skirt","description":"The Grey Pencil Skirt brings classic tailoring codes together with a sculptural, modern silhouette, making it a strong and timeless wardrobe piece.\n\nIts refined micro-check/houndstooth texture in grey and black is complemented by a high waist and corset-effect waistband that follows the figure. The shape-retaining fabric and fitted midi cut create a polished, confident look.\n\nKey features:\n• Cut: High waist, wide corset-effect waistband, button detail and fitted midi pencil shape\n• Detail: Finely worked micro-check/houndstooth texture and back slit\n• Fabric texture: A substantial, flexible woven fabric designed to hold its shape\n• Styling: Pair with ivory or white silk blouses, fine-gauge turtlenecks and stilettos for effortless polish at work or daytime occasions.","fabric":"Wool & polyester","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"grey-houndstooth-yuksek-bel-kalem-etek","locale":"ar","source_hash":"e788e2886a999c4f6bf9e01d73441af8bbc7c7717a56bb06d45fb436fd10b1be","payload":{"name":"تنورة قلم رمادية بنقشة قدم الغراب وخصر مرتفع","description":"تجمع التنورة الرمادية بقصة القلم بين تفاصيل الخياطة الكلاسيكية وقوام عصري ذي طابع نحتي، لتكون قطعة أساسية قوية وخالدة.\n\nيكتمل ملمسها الراقي بنقشة مربعات دقيقة/قدم الغراب بدرجات الرمادي والأسود مع خصر مرتفع وحزام ذي تأثير مشد يحدد القوام. يمنحها القماش الذي يحافظ على شكله والقصة الميدي المحددة إطلالة متقنة وواثقة.\n\nأبرز التفاصيل:\n• القصّة: خصر مرتفع، وحزام عريض بتأثير المشد، وتفصيل أزرار، وقصة قلم ميدي محددة\n• التفصيل: ملمس مربعات دقيقة/قدم الغراب مشغول بعناية وفتحة خلفية\n• ملمس القماش: قماش منسوج متماسك ومرن يحافظ على شكله\n• اقتراح تنسيق: نسّقيها مع بلوزة حريرية بلون عاجي أو أبيض، أو كنزة رقيقة بياقة عالية، وحذاء بكعب رفيع لإطلالة أنيقة للعمل أو لمناسبات النهار.","fabric":"صوف وبوليستر","care":"يُنظف جافاً فقط بطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"indigo-fermuarli-islemeli-denim-tulum","locale":"en","source_hash":"cf2949a854b364f1b220018b13ce9d63f453bab100dac55a2e846d7b80010181","payload":{"name":"Indigo Embellished Zip-Front Denim Jumpsuit","description":"The Indigo Jumpsuit pairs denim style with dynamic, refined details for an effortless yet confident look.\n\nA high neckline, full-length metal front zip and sleeveless shape balance masculine and feminine lines. Tone-on-tone beaded embroidered appliqués at the chest and side pockets add subtle sparkle, while light fringe at the pocket openings and hems brings a bohemian-luxe note. The wide-leg cut creates a fluid, elongated silhouette.\n\nKey features:\n• Cut: High neck, metal front zip, sleeveless, high waist and wide legs\n• Detail: Special bead/stone embroidered appliqués at the chest and pockets, with fringed pocket edges and hems\n• Fabric texture: A substantial, shape-retaining denim/crepe texture\n• Styling: Pair with black leather heeled boots or platform sandals for a modern city look that moves from day to evening.","fabric":"Cotton & polyester","care":"Dry clean only using a delicate process, or hand-wash in cold water. Dry flat; do not hang."}},{"entity_id":"indigo-fermuarli-islemeli-denim-tulum","locale":"ar","source_hash":"cf2949a854b364f1b220018b13ce9d63f453bab100dac55a2e846d7b80010181","payload":{"name":"جمبسوت دنيم Indigo مطرّز بسحاب","description":"يجمع جمبسوت Indigo بين أسلوب الدنيم والتفاصيل الحيوية الراقية لإطلالة واثقة بلا تكلف.\n\nتوازن الياقة العالية والسحاب المعدني الأمامي الممتد والقصة بلا أكمام بين الخطوط المستوحاة من القصات الرجالية والأنثوية. وتضيف الزخارف المطرزة بالخرز بدرجات متقاربة على الصدر والجيوب الجانبية بريقاً هادئاً، فيما تضفي الهدبات الخفيفة عند فتحات الجيوب والحواف لمسة بوهيمية فاخرة. تمنح القصة الواسعة الساقين مظهراً انسيابياً وطويلاً.\n\nأبرز التفاصيل:\n• القصّة: ياقة عالية، وسحاب معدني أمامي، وبلا أكمام، وخصر مرتفع وساقان واسعتان\n• التفصيل: زخارف خاصة مطرزة بالخرز/الأحجار على الصدر والجيوب، مع حواف مهدبة للجيوب وأطراف الساقين\n• ملمس القماش: ملمس دنيم/كريب متماسك يحافظ على شكله\n• اقتراح تنسيق: نسّقيه مع حذاء أسود جلدي بكعب أو صنادل بمنصة لإطلالة عصرية تنتقل من النهار إلى المساء.","fabric":"قطن وبوليستر","care":"يُنظف جافاً فقط بطريقة لطيفة، أو يُغسل يدوياً بماء بارد. يُجفف مفروداً ولا يُعلّق."}},{"entity_id":"ivory-bel-drapeli-saten-hakim-yaka-gomlek","locale":"en","source_hash":"2418562d377fd4d97550a322abe4c7c9ca2f8688af6ce543c7dd405f5bf6c292","payload":{"name":"Ivory Draped-Waist Satin Mandarin-Collar Shirt","description":"The Ivory Shirt pairs the subtle sheen of satin with sculptural details for a clean, sophisticated look.\n\nA mandarin collar, pearlescent buttons and fine pleated draping around the waist shape the figure. Style it with fluid high-waisted trousers for a monochrome occasion look, or wear it with a pencil skirt for a modern office outfit.\n\nKey features:\n• Cut: Mandarin collar, long sleeves with cuffs and a fitted, corset-like draped waist\n• Texture: Lustrous, fluid luxury satin\n• Styling: Complete the look with high-waisted ecru satin trousers and gold-tone accessories.","fabric":"Medina silk","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"ivory-bel-drapeli-saten-hakim-yaka-gomlek","locale":"ar","source_hash":"2418562d377fd4d97550a322abe4c7c9ca2f8688af6ce543c7dd405f5bf6c292","payload":{"name":"قميص Ivory ساتان بياقة صينية ودرابيه عند الخصر","description":"يجمع قميص Ivory بين اللمعان الهادئ للساتان والتفاصيل النحتية لإطلالة بسيطة وراقية.\n\nتحدد القوامَ ياقةٌ صينية وأزرار لؤلؤية ودرابيه بكسرات دقيقة حول الخصر. نسّقيه مع بنطال منسدل بخصر مرتفع لإطلالة أحادية اللون للمناسبات، أو ارتديه مع تنورة قلم لإطلالة عمل عصرية.\n\nأبرز التفاصيل:\n• القصّة: ياقة صينية، وأكمام طويلة بأساور، وقصة محددة عند الخصر بتأثير المشد والدرابيه\n• الملمس: ساتان فاخر لامع وانسيابي\n• اقتراح تنسيق: أكملي الإطلالة ببنطال ساتان إكرو بخصر مرتفع وإكسسوارات بلون ذهبي.","fabric":"حرير المدينة","care":"يُنظف جافاً فقط بطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"ivory-gold-islemeli-asimetrik-volanli-ceket-takim","locale":"en","source_hash":"127eb04f292b60feb5a50fd281bb9c0eb5f0150372ca8c90e2a8eff7a109a244","payload":{"name":"Ivory Gold-Embroidered Asymmetric Ruffle Suit","description":"The Ivory Suit brings NRS Studio's quiet-luxury aesthetic together with statement tailoring details, making it a refined choice for special occasions.\n\nThe ecru design is crowned by a gold-toned wing-shaped brooch embroidery, hand-finished at the right shoulder. Its collarless V neckline and asymmetric draped ruffle extending down from the right hem create a sculptural shape. Fluid, high-waisted wide-leg trousers with a pressed crease complete the look with a lengthening line and timeless presence.\n\nKey features:\n• Cut: Collarless V-neck jacket with an asymmetric draped ruffle at the right hem; high-waisted wide-leg trousers\n• Detail: Hand-finished gold-tone bead and sequin wing-brooch motif at the right shoulder; concealed closure\n• Fabric texture: A substantial, fluid crepe designed to hold its shape\n• Styling: Pair with ecru stilettos and minimal gold-tone earrings for a wedding, occasion or special evening event.","fabric":"Silk crepe & satin","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"ivory-gold-islemeli-asimetrik-volanli-ceket-takim","locale":"ar","source_hash":"127eb04f292b60feb5a50fd281bb9c0eb5f0150372ca8c90e2a8eff7a109a244","payload":{"name":"طقم Ivory بتطريز ذهبي وكشكش غير متماثل","description":"يجمع طقم Ivory بين أسلوب الفخامة الهادئة لدى NRS Studio وتفاصيل خياطة لافتة، ليكون خياراً راقياً للمناسبات الخاصة.\n\nيتوّج التصميم بلون الإكرو تطريز بروش على شكل جناح بدرجة ذهبية عند الكتف الأيمن، منفذ بتشطيب يدوي. وتمنح الياقة V بلا طية وامتداد الكشكش المنسدل غير المتماثل من الحافة اليمنى شكلاً نحتياً. ويكمل الإطلالة بنطال واسع وانسيابي بخصر مرتفع وخط كي، ليمنح القوام مظهراً أطول وحضوراً خالداً.\n\nأبرز التفاصيل:\n• القصّة: سترة بياقة V بلا طية وكشكش منسدل غير متماثل عند الحافة اليمنى؛ وبنطال واسع الساق بخصر مرتفع\n• التفصيل: زخرفة بروش جناح مطرزة يدوياً بالخرز والترتر بلون ذهبي عند الكتف الأيمن؛ وإغلاق مخفي\n• ملمس القماش: كريب متماسك وانسيابي يحافظ على شكله\n• اقتراح تنسيق: نسّقيه مع حذاء إكرو بكعب رفيع وأقراط بسيطة بلون ذهبي لحفل زفاف أو مناسبة أو أمسية خاصة.","fabric":"كريب حريري وساتان","care":"يُنظف جافاً فقط بطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"ivory-halter-yaka-drape-detayli-genis-paca-takim","locale":"en","source_hash":"1af3d2981c84ed3bbaed3c6306119b457f16180290d11b0ead854f6f6261c3e9","payload":{"name":"Ivory Draped Halter-Neck Blouse","description":"The Ivory Blouse brings a quiet-luxury aesthetic together with fluid, sculptural lines, making it a natural choice for effortless elegance.\n\nThe sleeveless design pairs a halter neckline with delicate gathered draping around the neck. Its soft, fluid shape falls gently away from the body. It works beautifully with high-waisted trousers or skirts, adding a sophisticated touch to both daytime looks and evening occasions.\n\nKey features:\n• Cut: Halter neck, sleeveless, relaxed fluid silhouette\n• Detail: Delicately gathered draped panel at the neck and concealed fastening at the back\n• Fabric texture: A soft, fluid fabric with a silky feel\n• Styling: Pair with high-waisted ecru or black tailored trousers for effortless occasion dressing, or layer under a blazer.","fabric":"Cotton & viscose","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"ivory-halter-yaka-drape-detayli-genis-paca-takim","locale":"ar","source_hash":"1af3d2981c84ed3bbaed3c6306119b457f16180290d11b0ead854f6f6261c3e9","payload":{"name":"بلوزة Ivory بياقة هالتر وتفصيل درابيه","description":"تجمع بلوزة Ivory بين أسلوب الفخامة الهادئة والخطوط الانسيابية ذات الطابع النحتي، لتكون خياراً طبيعياً للأناقة بلا تكلف.\n\nيمزج التصميم بلا أكمام ياقة هالتر مع كسرات درابيه رقيقة حول الرقبة. وينسدل شكلها الناعم بانسياب بعيداً عن الجسم. وتنسجم مع البنطال أو التنورة بخصر مرتفع، لتضيف لمسة راقية إلى إطلالات النهار والمناسبات المسائية.\n\nأبرز التفاصيل:\n• القصّة: ياقة هالتر، بلا أكمام، وقوام مريح وانسيابي\n• التفصيل: لوحة درابيه مجمعة برقة عند الرقبة وإغلاق مخفي من الخلف\n• ملمس القماش: قماش ناعم وانسيابي بملمس حريري\n• اقتراح تنسيق: نسّقيها مع بنطال مفصل بلون إكرو أو أسود وخصر مرتفع لإطلالة مناسبة أنيقة بلا تكلف، أو ارتديها تحت سترة.","fabric":"قطن وفيسكوز","care":"يُنظف جافاً فقط بطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"ivory-sculpted-asimetrik-yelek-takim","locale":"en","source_hash":"555574fa230d7133473a016b2b4900d1020b99b65948eb780ea051f33d3f9d7d","payload":{"name":"Ivory Sculpted Asymmetric Waistcoat Suit","description":"The Ivory Sculpted Suit pairs the clarity of ivory tones with modern, sculptural tailoring for a confident look with ease.\n\nThe sleeveless top is distinguished by a high stand collar and layered asymmetric draping over the left shoulder. A gold-tone metal belt with a chain detail defines the waist with sculptural elegance. The fluid, high-waisted wide-leg trousers have a pressed crease that visually lengthens the legs and balances the silhouette.\n\nKey features:\n• Cut: Stand-collar sleeveless top with layered asymmetric lapel detail; high-waisted fluid wide-leg palazzo trousers\n• Detail: Custom belt with a gold-tone chain and metal buckle at the waist; asymmetric hem\n• Fabric texture: A substantial, lightly textured luxury crepe with fluid drape that holds its shape\n• Styling: Finish with cream leather stilettos and a tonal clutch for a confident look at occasions and polished city events, from day to evening.","fabric":"Marco Miotti","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"ivory-sculpted-asimetrik-yelek-takim","locale":"ar","source_hash":"555574fa230d7133473a016b2b4900d1020b99b65948eb780ea051f33d3f9d7d","payload":{"name":"طقم Ivory Sculpted بفيست غير متماثل","description":"يجمع طقم Ivory Sculpted بين صفاء درجات العاجي والخياطة العصرية ذات الطابع النحتي لإطلالة واثقة بلا تكلف.\n\nيتميز الجزء العلوي بلا أكمام بياقة قائمة عالية ودرابيه غير متماثل متعدد الطبقات فوق الكتف الأيسر. ويحدد الخصر حزام معدني بلون ذهبي وتفصيل سلسلة، بلمسة نحتية أنيقة. أما البنطال الواسع والانسيابي بخصر مرتفع وخط كي فيطيل الساقين بصرياً ويوازن القوام.\n\nأبرز التفاصيل:\n• القصّة: جزء علوي بلا أكمام بياقة قائمة وتفصيل طية غير متماثلة متعددة الطبقات؛ وبنطال بالازو واسع وانسيابي بخصر مرتفع\n• التفصيل: حزام خاص بسلسلة وإبزيم معدني بلون ذهبي عند الخصر؛ وحافة غير متماثلة\n• ملمس القماش: كريب فاخر متماسك وخفيف الملمس بانسدال انسيابي يحافظ على شكله\n• اقتراح تنسيق: أكملي الإطلالة بحذاء كريمي جلدي بكعب رفيع وحقيبة يد بدرجات متناسقة لإطلالة واثقة في المناسبات والفعاليات الأنيقة من النهار إلى المساء.","fabric":"Marco Miotti","care":"يُنظف جافاً فقط بطريقة لطيفة. يُكوى من الداخل على حرارة منخفضة."}},{"entity_id":"ivory-sculpted-asimetrik-yelek-takim-kopya","locale":"en","source_hash":"d11cd142fb1d820f6da77beb6e71902409b5d2130818c71abd9504acd09ab255","payload":{"name":"Ivory Sculpted Asymmetric Waistcoat","description":"The Ivory Sculpted Suit pairs the clarity of ivory tones with modern, sculptural tailoring for a confident look with ease.\n\nThe sleeveless top is distinguished by a high stand collar and layered asymmetric draping over the left shoulder. A gold-tone metal belt with a chain detail defines the waist with sculptural elegance. The fluid, high-waisted wide-leg trousers have a pressed crease that visually lengthens the legs and balances the silhouette.\n\nKey features:\n• Cut: Stand-collar sleeveless top with layered asymmetric lapel detail; high-waisted fluid wide-leg palazzo trousers\n• Detail: Custom belt with a gold-tone chain and metal buckle at the waist; asymmetric hem\n• Fabric texture: A substantial, lightly textured luxury crepe with fluid drape that holds its shape\n• Styling: Finish with cream leather stilettos and a tonal clutch for a confident look at occasions and polished city events, from day to evening.","fabric":"Marco Miotti","care":"Dry clean only using a delicate process. Iron inside out at a low temperature."}},{"entity_id":"ivory-sculpted-asimetrik-yelek-takim-kopya","locale":"ar","source_hash":"d11cd142fb1